/*
 * Estilos de MSG-01 · Lista de Hilos (capa pantalla).
 *
 * El HTML aprobado pide superficies blancas (#fff) para inputs y botones y el
 * sistema de tokens no define `--bw-white`; se usa el neutro claro más próximo,
 * `--bw-warm-cream`, y se documenta aquí.
 */

.screen {
  display: flex;
  flex-direction: column;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  max-width: 560px;
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.errorBanner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
}

.errorIcon {
  margin-top: 1px;
  color: var(--bw-sensitive-text);
}

.errorText {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-sensitive-text);
}

.actionsBar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
  min-width: 220px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-warm-cream);
  color: var(--bw-input-text);
  font: inherit;
  font-size: 13px;
  outline: none;
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.newContact {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.primaryButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s;
}

.primaryButton:hover:not(:disabled) {
  opacity: 0.88;
}

.primaryButton:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.scopeNote {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

.resultCount {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder); /* #9BA4B0: token con ese gris exacto */
}

.loadingState {
  padding: 40px 24px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  font-size: 13px;
  color: var(--bw-steel-mist);
  text-align: center;
}

.pagination {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 14px;
}

.pageButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageButton:disabled {
  cursor: default;
}

.pageActive,
.pageActive:disabled {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

.pageArrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  color: var(--bw-input-placeholder);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageArrow:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageArrow:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

