import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos.
 *
 * Pantalla completa: posee el estado de búsqueda, el de página y la llamada a
 * `fetchThreadPage`. `ThreadList` es el componente presentacional de abajo.
 *
 * La prop `onOpenThread` forma parte de la firma pública porque el shell se
 * cableó después de escribir esta pantalla (F-118), pero MSG-02 no está en el
 * alcance del MVP: esta pantalla la recibe y no la usa.
 */
interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** F-118: declarada para que el repo compile. No se usa: MSG-02 no existe. */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Extrae lo que de verdad explica un fallo de red.
 *
 * PostgREST no siempre rechaza con un `Error`: devuelve objetos planos
 * `{ code, message }`. Si se hiciera `String(e)` se pintaría `[object Object]`
 * y el `PGRST201` que explica el fallo entero se perdería (F-020 / F-128).
 */
function describeError(cause: unknown): string {
  if (cause instanceof Error) return cause.message;
  if (typeof cause === 'object' && cause !== null) {
    const record = cause as Record<string, unknown>;
    const code = typeof record.code === 'string' || typeof record.code === 'number' ? String(record.code) : '';
    const message = typeof record.message === 'string' ? record.message : '';
    const detail = [code, message].filter(Boolean).join(': ');
    if (detail) return detail;
  }
  return String(cause);
}

/**
 * MSG-02 no está entre las pantallas del MVP: abrir un hilo no lleva a ningún
 * sitio, así que el clic en las filas no hace nada.
 */
function noopThreadOpen(_threadId: string): void {
  /* Intencionadamente vacío. */
}

export function Messages({ profile, now }: MessagesProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchDraft, setSearchDraft] = useState('');
  const [page, setPage] = useState(1);
  const [pageData, setPageData] = useState<ThreadPage>({ threads: [], total: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: searchTerm, page })
      .then((nextPage) => {
        if (cancelled) return;
        setPageData(nextPage);
      })
      .catch((cause: unknown) => {
        if (cancelled) return;
        setError(describeError(cause));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, searchTerm, page]);

  function applySearch() {
    setPage(1);
    setSearchTerm(searchDraft);
  }

  const totalPages = pageCount(pageData.total);
  const showInitialLoading = loading && pageData.threads.length === 0 && !error;

  return (
    <section className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      {error ? (
        <div className={styles.errorBanner} role="alert">
          <i className={`ti ti-alert-circle ${styles.errorIcon}`} aria-hidden="true" />
          <p className={styles.errorText}>
            <strong>No se pudieron cargar los hilos.</strong> {error}
          </p>
        </div>
      ) : null}

      <div className={styles.actionsBar}>
        {/* La spec filtra al pulsar Enter, así que el input guarda su borrador y
            la búsqueda aplicada vive en `searchTerm`. */}
        <form
          className={styles.searchWrap}
          onSubmit={(event) => {
            event.preventDefault();
            applySearch();
          }}
        >
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={searchDraft}
            onChange={(event) => setSearchDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                applySearch();
              }
            }}
          />
        </form>

        <div className={styles.newContact}>
          {/* DIR-01 no está en el alcance del MVP: el control existe pero está
              deshabilitado y su motivo es visible. */}
          <button type="button" className={styles.primaryButton} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.scopeNote} data-testid="directorio-scope">
            Abrir DIR-01 (Directorio) queda fuera del MVP.
          </span>
        </div>

        <span className={styles.resultCount} data-testid="pag-info">
          {pageData.total} hilos · Página {page} de {totalPages}
        </span>
      </div>

      {error ? null : showInitialLoading ? (
        <div className={styles.loadingState} role="status">
          Cargando hilos…
        </div>
      ) : (
        <ThreadList threads={pageData.threads} now={now} onOpen={noopThreadOpen} />
      )}

      {!loading && !error && totalPages > 1 ? (
        <nav className={styles.pagination} aria-label="Paginación de hilos">
          <button
            type="button"
            className={styles.pageArrow}
            disabled={page <= 1}
            aria-label="Página anterior"
            onClick={() => setPage((current) => Math.max(1, current - 1))}
          >
            ‹
          </button>
          {Array.from({ length: totalPages }, (_, index) => index + 1).map((number) => (
            <button
              key={number}
              type="button"
              className={number === page ? `${styles.pageButton} ${styles.pageActive}` : styles.pageButton}
              disabled={number === page}
              aria-current={number === page ? 'page' : undefined}
              onClick={() => setPage(number)}
            >
              {number}
            </button>
          ))}
          <button
            type="button"
            className={styles.pageArrow}
            disabled={page >= totalPages}
            aria-label="Página siguiente"
            onClick={() => setPage((current) => Math.min(totalPages, current + 1))}
          >
            ›
          </button>
        </nav>
      ) : null}
    </section>
  );
}

