/*
 * Módulo de estilos de la lista de hilos (MSG-01).
 *
 * El HTML aprobado pinta las tarjetas/filas de la lista sobre blanco puro
 * (#fff) y el sistema de tokens no define `--bw-white`. Se usa el neutro claro
 * más próximo, `--bw-warm-cream`, y se deja dicho aquí para que el relevo no lo
 * confunda con un crema intencional.
 */

.threadList {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.threadItem + .threadItem {
  border-top: 1px solid var(--bw-divider-mist);
}

.threadButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  width: 100%;
  margin: 0;
  padding: 14px 18px;
  border: none;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.1s;
}

.threadButton:hover {
  background: var(--bw-row-hover-tint);
}

.threadButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadOrg {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.threadMeta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.threadTime {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder); /* #9BA4B0: el token con ese gris exacto */
  white-space: nowrap;
}

.threadBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadPreview {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  flex-shrink: 0;
  border: 1px solid transparent;
  border-radius: 2px;
  padding: 2px 7px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.toneNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

.toneInfo {
  /* rgba azul 0.08 del mock aprobado; borde azul 0.30 al no existir token .20 */
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border-color: var(--bw-chip-active-border);
}

.toneWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

.toneSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border-color: var(--bw-badge-success-border);
}

.toneClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border-color: var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 48px 24px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  text-align: center;
}

.emptyText {
  max-width: 440px;
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-ink-steel-soft);
}

.primaryButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.primaryButton:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.scopeNote {
  font-size: 12px;
  color: var(--bw-steel-mist);
}

