import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * La clase por tono del badge de estado.
 *
 * F-143: con `noUncheckedIndexedAccess` cualquier propiedad del módulo CSS se
 * tipa `string | undefined`, así que el diccionario declara el tipo completo y
 * el `?? ''` resuelve el hueco en el único sitio donde se consume.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.toneNeutral,
  info: styles.toneInfo,
  warn: styles.toneWarn,
  success: styles.toneSuccess,
  closed: styles.toneClosed,
};

interface ThreadListProps {
  /** Hilos ya paginados y ordenados por la API. Este componente no ordena. */
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** Avisa con el id del hilo — MSG-02 se abrirá en otra pantalla. */
  onOpen: (threadId: string) => void;
}

/**
 * Lista de hilos de MSG-01. Presentacional: pinta las filas que recibe y no
 * carga ni pagina datos.
 *
 * Cada fila es un `<li>` sin `role` (F-131): el `li` conserva su rol implícito
 * `listitem` y el botón de apertura vive DENTRO de él. Poner el `role` encima
 * del `<li>` rompería la consulta por `listitem`.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.primaryButton} disabled>
          Ir al Directorio
        </button>
        {/* F-128: el motivo visible de que el botón esté apagado. Fuera de
            cualquier `<ul>` para que el estado vacío no deje listitems. */}
        <span className={styles.scopeNote}>El Directorio queda fuera del MVP.</span>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        const toneClass = TONE_CLASS[tone] ?? '';
        const timestamp = relativeTime(thread.lastItemAt, now ?? new Date());
        return (
          <li key={thread.id} className={styles.threadItem}>
            <button
              type="button"
              className={styles.threadButton}
              aria-label={`Abrir hilo con ${thread.counterpartyName}`}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.threadTop}>
                <span className={styles.threadOrg}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                ) : null}
              </span>
              <span className={styles.threadMeta}>
                {timestamp ? (
                  <time className={styles.threadTime} dateTime={thread.lastItemAt}>
                    {timestamp}
                  </time>
                ) : null}
              </span>
              <span className={styles.threadBottom}>
                <span className={styles.threadPreview}>{previewLabel(thread.lastItem)}</span>
                {/* La vista previa son metadatos únicamente: tipo de elemento y
                    referencia. Nunca contenido descifrado (spec §7). */}
                <span className={`${styles.stateBadge} ${toneClass}`}>{thread.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
